<script>
document.addEventListener("DOMContentLoaded", function () {

    const productosScroll =
        document.getElementById("productosScroll");

    const botonesAnterior = [
        document.getElementById("productosAnterior"),
        document.getElementById("productosAnteriorLateral")
    ];

    const botonesSiguiente = [
        document.getElementById("productosSiguiente"),
        document.getElementById("productosSiguienteLateral")
    ];

    const progreso =
        document.getElementById("productosProgreso");

    if (!productosScroll) {
        console.error("No se encontró #productosScroll");
        return;
    }


    /* =========================================
       CALCULAR ANCHO DE UNA TARJETA
    ========================================== */

    function obtenerDistanciaScroll() {

        const tarjeta =
            productosScroll.querySelector(
                ".catalogo-producto-card"
            );

        if (!tarjeta) {
            return 350;
        }

        const estilos =
            window.getComputedStyle(productosScroll);

        const separacion =
            parseFloat(estilos.columnGap) ||
            parseFloat(estilos.gap) ||
            18;

        return tarjeta.getBoundingClientRect().width +
            separacion;
    }


    /* =========================================
       MOVER EL CARRUSEL
    ========================================== */

    function moverCarrusel(direccion) {

        productosScroll.scrollBy({
            left: obtenerDistanciaScroll() * direccion,
            behavior: "smooth"
        });

    }


    botonesAnterior.forEach(function (boton) {

        if (!boton) {
            return;
        }

        boton.addEventListener("click", function (evento) {

            evento.preventDefault();
            evento.stopPropagation();

            moverCarrusel(-1);

        });

    });


    botonesSiguiente.forEach(function (boton) {

        if (!boton) {
            return;
        }

        boton.addEventListener("click", function (evento) {

            evento.preventDefault();
            evento.stopPropagation();

            moverCarrusel(1);

        });

    });


    /* =========================================
       ACTUALIZAR BARRA DE PROGRESO
    ========================================== */

    function actualizarProgreso() {

        if (!progreso) {
            return;
        }

        const anchoTotal =
            productosScroll.scrollWidth;

        const anchoVisible =
            productosScroll.clientWidth;

        const scrollMaximo =
            anchoTotal - anchoVisible;

        if (scrollMaximo <= 0) {

            progreso.style.width = "100%";
            progreso.style.transform =
                "translateX(0)";

            return;
        }

        const porcentajeVisible =
            anchoVisible / anchoTotal;

        const anchoIndicador = Math.max(
            porcentajeVisible * 100,
            15
        );

        const posicionScroll =
            productosScroll.scrollLeft /
            scrollMaximo;

        const recorridoDisponible =
            100 - anchoIndicador;

        const posicionIndicador =
            posicionScroll * recorridoDisponible;

        progreso.style.width =
            anchoIndicador + "%";

        progreso.style.transform =
            "translateX(" +
            (
                posicionIndicador *
                100 /
                anchoIndicador
            ) +
            "%)";

    }


    productosScroll.addEventListener(
        "scroll",
        actualizarProgreso,
        { passive: true }
    );

    window.addEventListener(
        "resize",
        actualizarProgreso
    );


    /* =========================================
       PERMITIR ARRASTRAR CON EL MOUSE
    ========================================== */

    let arrastrando = false;
    let inicioX = 0;
    let scrollInicial = 0;
    let movimientoRealizado = false;

    productosScroll.addEventListener(
        "mousedown",
        function (evento) {

            if (
                evento.target.closest(
                    ".catalogo-producto-boton"
                )
            ) {
                return;
            }

            arrastrando = true;
            movimientoRealizado = false;

            inicioX = evento.pageX;
            scrollInicial =
                productosScroll.scrollLeft;

            productosScroll.style.cursor =
                "grabbing";

        }
    );

    productosScroll.addEventListener(
        "mousemove",
        function (evento) {

            if (!arrastrando) {
                return;
            }

            evento.preventDefault();

            const distancia =
                evento.pageX - inicioX;

            if (Math.abs(distancia) > 5) {
                movimientoRealizado = true;
            }

            productosScroll.scrollLeft =
                scrollInicial - distancia;

        }
    );

    function detenerArrastre() {

        arrastrando = false;

        productosScroll.style.cursor =
            "grab";

    }

    productosScroll.addEventListener(
        "mouseup",
        detenerArrastre
    );

    productosScroll.addEventListener(
        "mouseleave",
        detenerArrastre
    );

    window.addEventListener(
        "mouseup",
        detenerArrastre
    );


    /* Evitar abrir el modal si se arrastró */
    productosScroll.addEventListener(
        "click",
        function (evento) {

            if (!movimientoRealizado) {
                return;
            }

            evento.preventDefault();
            evento.stopPropagation();

            movimientoRealizado = false;

        },
        true
    );


    actualizarProgreso();

});
</script>








