    let catalogoActual = null;

    function normalizarProducto(datos) {
        return { tipo: datos[0], nombre: datos[1], descripcion: datos[2], imagen: datos[3] };
    }

    function crearTarjeta(datos) {
        const producto = Array.isArray(datos) ? normalizarProducto(datos) : datos;
        const articulo = document.createElement("article");
        articulo.className = "interruptor-modal-card";
        articulo.innerHTML = `
            <div class="interruptor-card-imagen">
                <button type="button" class="interruptor-ampliar-imagen" aria-label="Ampliar imagen de ${producto.nombre}">
                    <img src="${producto.imagen}" alt="${producto.nombre}" loading="lazy">
                </button>
                <span class="interruptor-card-ampliar"><i class="fa-solid fa-expand"></i></span>
            </div>
            <div class="interruptor-card-contenido">
                <span class="interruptor-card-tipo">${producto.tipo}</span>
                <h4>${producto.nombre}</h4>
                <p>${producto.descripcion}</p>
                <a href="https://wa.me/524421822409?text=${encodeURIComponent("Hola, deseo solicitar información sobre " + producto.nombre + ".")}"
                   target="_blank" rel="noopener" class="interruptor-card-enlace">
                    Consultar producto <i class="fa-solid fa-arrow-right"></i>
                </a>
            </div>`;
        articulo.querySelector(".interruptor-ampliar-imagen").addEventListener("click", () => abrirLightbox(producto));
        return articulo;
    }

    function mostrarCategoria(clave) {
        if (!catalogoActual) return;
        const categoria = catalogoActual.categorias[clave];
        if (!categoria) return;
        etiquetaCategoria.textContent = catalogoActual.titulo;
        tituloCategoria.textContent = categoria.titulo;
        descripcionCategoria.textContent = categoria.descripcion;
        productosContenedor.innerHTML = "";
        categoria.productos.forEach(p => productosContenedor.appendChild(crearTarjeta(p)));
        productosContenedor.scrollLeft = 0;
        requestAnimationFrame(actualizarProgreso);
    }

    function crearMenuCatalogo(catalogo) {
        menu.innerHTML = "";
        Object.entries(catalogo.categorias).forEach(([clave, categoria], indice) => {
            const boton = document.createElement("button");
            boton.type = "button";
            boton.className = "interruptores-menu-item" + (indice === 0 ? " active" : "");
            boton.dataset.categoria = clave;
            boton.innerHTML = `
                <span class="interruptores-menu-icono"><i class="${categoria.icono}"></i></span>
                <span class="interruptores-menu-texto">
                    <strong>${categoria.titulo}</strong>
                    <small>${categoria.subtitulo}</small>
                </span>
                <i class="fa-solid fa-chevron-right"></i>`;
            boton.addEventListener("click", function () {
                menu.querySelectorAll(".interruptores-menu-item").forEach(i => i.classList.remove("active"));
                boton.classList.add("active");
                mostrarCategoria(clave);
            });
            menu.appendChild(boton);
        });
    }

    function obtenerDistancia() {
        const tarjeta = productosContenedor.querySelector(".interruptor-modal-card");
        if (!tarjeta) return 300;
        const gap = parseFloat(getComputedStyle(productosContenedor).columnGap) || 16;
        return tarjeta.offsetWidth + gap;
    }

    botonAnterior?.addEventListener("click", () => productosContenedor.scrollBy({left:-obtenerDistancia(),behavior:"smooth"}));
    botonSiguiente?.addEventListener("click", () => productosContenedor.scrollBy({left:obtenerDistancia(),behavior:"smooth"}));

    function actualizarProgreso() {
        if (!progreso) return;
        const total = productosContenedor.scrollWidth;
        const visible = productosContenedor.clientWidth;
        const maximo = total - visible;
        if (maximo <= 0) {
            progreso.style.width = "100%";
            progreso.style.transform = "translateX(0)";
            return;
        }
        const ancho = Math.max((visible / total) * 100, 15);
        const posicion = (productosContenedor.scrollLeft / maximo) * (100 - ancho);
        progreso.style.width = ancho + "%";
        progreso.style.transform = "translateX(" + (posicion * 100 / ancho) + "%)";
    }
    productosContenedor.addEventListener("scroll", actualizarProgreso, {passive:true});
    window.addEventListener("resize", actualizarProgreso);

    function abrirLightbox(producto) {
        lightboxImagen.src = producto.imagen;
        lightboxImagen.alt = producto.nombre;
        lightboxTitulo.textContent = producto.nombre;
        lightbox.classList.add("active");
        lightbox.setAttribute("aria-hidden","false");
    }
    function cerrarLightbox() {
        lightbox.classList.remove("active");
        lightbox.setAttribute("aria-hidden","true");
        setTimeout(() => { lightboxImagen.src = ""; }, 300);
    }
    lightboxCerrar?.addEventListener("click", cerrarLightbox);
    lightbox?.addEventListener("click", e => { if (e.target === lightbox) cerrarLightbox(); });
    document.addEventListener("keydown", e => { if (e.key === "Escape" && lightbox.classList.contains("active")) cerrarLightbox(); });

    modal.addEventListener("show.bs.modal", function (evento) {
        const claveCatalogo = evento.relatedTarget?.dataset.producto || "interruptores";
        catalogoActual = catalogosProductos[claveCatalogo] || catalogosProductos.interruptores;

        modal.querySelector("[data-modal-catalogo-titulo]").textContent = catalogoActual.titulo;
        modal.querySelector("[data-modal-catalogo-descripcion]").textContent = catalogoActual.descripcion;
        modal.querySelector("[data-menu-titulo]").textContent = catalogoActual.menuTitulo;

        crearMenuCatalogo(catalogoActual);
        const primeraCategoria = Object.keys(catalogoActual.categorias)[0];
        mostrarCategoria(primeraCategoria);

        if (cotizar) {
            cotizar.href = "https://wa.me/524421822409?text=" +
                encodeURIComponent("Hola, deseo solicitar información sobre " + catalogoActual.titulo + ".");
        }
    });

    modal.addEventListener("hidden.bs.modal", cerrarLightbox);
});
</script>